do $$ declare v_oid oid;v_def text;v_old text:='begin select location_id,created_at into v_loc,v_origin_created';v_new text:='begin if private.gst_v520_authoritative_context(p_tenant_id,p_entity_type) then return null;end if;select location_id,created_at into v_loc,v_origin_created';begin select p.oid into v_oid from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private' and p.proname='v4_accounting_post_document' and pg_get_function_identity_arguments(p.oid)='p_tenant_id uuid, p_entity_type text, p_entity_id uuid';if v_oid is null then raise exception 'Legacy accounting poster not found';end if;v_def:=pg_get_functiondef(v_oid);if position('gst_v520_authoritative_context(p_tenant_id,p_entity_type)' in v_def)=0 then if position(v_old in v_def)=0 then raise exception 'Legacy accounting poster did not match expected definition';end if;v_def:=replace(v_def,v_old,v_new);execute v_def;end if;end $$;
insert into public.thq_schema_releases(migration_no,schema_version,release_name,notes) values(238,'5.2.0-foundation','GST Legacy Accounting Guard','Adds a private authoritative-context guard to the legacy v4 document accounting poster. Both origin-trigger and explicit wrapper calls remain normal for v5.1, but return without generic Input/Output GST posting while a matching v5.2 atomic Sale/Purchase is being assembled.') on conflict(migration_no) do update set schema_version=excluded.schema_version,release_name=excluded.release_name,notes=excluded.notes;